window.dataLayer = window.dataLayer || [];
function gtag(){dataLayer.push(arguments);}
gtag('js', new Date());
gtag('config', 'UA-18403054-1');

body.script:
(function(){
    var fullres = document.createElement('script');
    fullres.async = true;
    fullres.src = 'https://t.fullres.net/vectorportal.js?'+(new Date()-new Date()%43200000);
    document.head.appendChild(fullres);
})();

window.localeCode       = 'en'
window.livewire_app_url = "vectorportal.com/en"
window.searchTotal      = ''
// add a 'no-results' class to BODY if no search results exist
document.addEventListener("DOMContentLoaded", function() {
    if (window.searchTotal == '0') {
        document.body.classList.add('no-results');
    }
});

document.addEventListener('DOMContentLoaded', () => {
    // track free vector download button clicks
    const downloadButton = document.querySelector('.button-lg--download');
    if (downloadButton) {
        downloadButton.addEventListener('click', () => {
            window.fullres ||= {events: []};
            window.fullres.events.push({ 
                key: 'freeDownloadClick'
            });
        });
    }
    // track API related result clicks
    const affiliateApiLinks = document.querySelectorAll('.stock-api-results a');
    affiliateApiLinks.forEach(link => {
        link.addEventListener('click', () => {
            window.fullres ||= {events: []};
            window.fullres.events.push({ 
                key: 'affiliateApiClick', 
                affiliateType: 'API Related Results'
            });
        });
    });
    // track affiliate discount code link clicks
    const affiliateDiscountLinks = document.querySelectorAll('.stock-section__title, .single-right__sstk a');
    affiliateDiscountLinks.forEach(link => {
        link.addEventListener('click', () => {
            window.fullres ||= {events: []};
            window.fullres.events.push({ 
                key: 'affiliatePromoClick', 
                affiliateType: 'Promo Code'
            });
        });
    });
});
